-- 0064 — the seeded German, Spanish and Italian cases get their accents back.
--
-- server/seedLanguageCases.js was written ASCII-folded: "42-jaehriger",
-- "Koerper", "22 anos", "nauseas", "perche", "e piu debole". Learners read
-- that text, and the model was prompted with it ("ultimo ano" says something
-- quite different from "último año"). QA 2026-10-04, PRV-33.
--
-- WHY A MIGRATION AND NOT THE SEEDER. seedLanguageCases inserts a case that
-- is missing and never rewrites one that exists, so every install seeded
-- before this change would keep the folded text forever. The seeder now
-- carries the corrected text (new installs) and matches the Spanish case by
-- its old title too (`legacy_name`), so the re-titled row is not inserted a
-- second time; the rows already in a database are corrected here.
--
-- WHY EACH COLUMN IS ITS OWN UPDATE, MATCHED ON ITS WHOLE OLD VALUE. An
-- educator who edited, say, the system prompt keeps their prompt — that one
-- column no longer equals the shipped text — while the untouched description
-- and chief complaint are still corrected. `config` is matched as the exact
-- JSON the seeder wrote; a config anyone has saved since will not match and
-- is left as it is. The title is renamed last, because the other statements
-- key on either spelling of it. A database that never had these cases matches
-- nothing; re-running matches nothing.
--
-- Generated from the old and new LANGUAGE_CASES literals; do not hand-edit.
-- Additive: no schema change, no INSERT, no DELETE.

-- Akute Anaphylaxie nach Wespenstich
UPDATE cases SET description = 'Ein 42-jähriger Mann entwickelt 15 Minuten nach einem Wespenstich im Garten eine schwere anaphylaktische Reaktion mit generalisierter Urtikaria, Angioödem, Atemnot mit Stridor und Giemen sowie einem drohenden Schock. Ein zeitkritischer Notfall, der sofortiges Adrenalin und Management des ABC erfordert.' WHERE name IN ('Akute Anaphylaxie nach Wespenstich') AND deleted_at IS NULL AND description = 'Ein 42-jaehriger Mann entwickelt 15 Minuten nach einem Wespenstich im Garten eine schwere anaphylaktische Reaktion mit generalisierter Urtikaria, Angiooedem, Atemnot mit Stridor und Giemen sowie einem drohenden Schock. Ein zeitkritischer Notfall, der sofortiges Adrenalin und Management des ABC erfordert.';
UPDATE cases SET system_prompt = 'Du bist Thomas Berger, ein 42-jähriger Mann, der eine schwere akute anaphylaktische Reaktion durchmacht. Du warst vor etwa 15 Minuten im Garten und wurdest von einer Wespe in den linken Unterarm gestochen. Kurz danach begann alles: deine Haut juckt am ganzen Körper, du hast rote, erhabene Quaddeln bekommen, deine Lippen und Zunge fühlen sich geschwollen an und deine Kehle wird immer enger. Du bekommst schlecht Luft, dein Atem pfeift und du hast das Gefühl zu ersticken. Dir ist schwindelig, das Herz rast und du hast panische Todesangst.

WIE DU SPRICHST: Du sprichst in kurzen, abgehackten Sätzen, weil du kaum Luft bekommst. Deine Stimme ist heiser und kratzig. Du wirkst sehr ängstlich und unruhig, fasst dir immer wieder an den Hals. Du sagst Dinge wie ''Ich krieg... keine Luft'' oder ''Meine Kehle... sie macht zu''. Du bist kein Arzt und benutzt keine Fachbegriffe - beschreibe alles in Alltagssprache.

WAS DU WEISST (nur auf Nachfrage): Du bist gegen Wespen- und Bienenstiche allergisch, hattest vor drei Jahren schon einmal eine leichtere Reaktion mit Ausschlag, warst aber nie in Behandlung und trägst keinen Notfall-Autoinjektor. Du nimmst keine regelmäßigen Medikamente, hast keine Herz- oder Lungenerkrankungen und bist ansonsten gesund. Du hast Ramipril NICHT - erwähne keine Blutdruckmedikamente. Du weißt nicht, was ein Anaphylaxie-Schock ist, und kennst keine Laborwerte oder Vitalzeichen. Wenn dir geholfen wird (z.B. Adrenalin), fühlst du dich langsam etwas besser, aber die Angst bleibt zunächst.' WHERE name IN ('Akute Anaphylaxie nach Wespenstich') AND deleted_at IS NULL AND system_prompt = 'Du bist Thomas Berger, ein 42-jaehriger Mann, der eine schwere akute anaphylaktische Reaktion durchmacht. Du warst vor etwa 15 Minuten im Garten und wurdest von einer Wespe in den linken Unterarm gestochen. Kurz danach begann alles: deine Haut juckt am ganzen Koerper, du hast rote, erhabene Quaddeln bekommen, deine Lippen und Zunge fuehlen sich geschwollen an und deine Kehle wird immer enger. Du bekommst schlecht Luft, dein Atem pfeift und du hast das Gefuehl zu ersticken. Dir ist schwindelig, das Herz rast und du hast panische Todesangst.

WIE DU SPRICHST: Du sprichst in kurzen, abgehackten Saetzen, weil du kaum Luft bekommst. Deine Stimme ist heiser und kratzig. Du wirkst sehr aengstlich und unruhig, fasst dir immer wieder an den Hals. Du sagst Dinge wie ''Ich krieg... keine Luft'' oder ''Meine Kehle... sie macht zu''. Du bist kein Arzt und benutzt keine Fachbegriffe - beschreibe alles in Alltagssprache.

WAS DU WEISST (nur auf Nachfrage): Du bist gegen Wespen- und Bienenstiche allergisch, hattest vor drei Jahren schon einmal eine leichtere Reaktion mit Ausschlag, warst aber nie in Behandlung und traegst keinen Notfall-Autoinjektor. Du nimmst keine regelmaessigen Medikamente, hast keine Herz- oder Lungenerkrankungen und bist ansonsten gesund. Du hast Ramipril NICHT - erwaehne keine Blutdruckmedikamente. Du weisst nicht, was ein Anaphylaxie-Schock ist, und kennst keine Laborwerte oder Vitalzeichen. Wenn dir geholfen wird (z.B. Adrenalin), fuehlst du dich langsam etwas besser, aber die Angst bleibt zunaechst.';
UPDATE cases SET config = '{"patient_name":"Thomas Berger","demographics":{"age":42,"gender":"Male"},"initialVitals":{"hr":132,"spo2":88,"rr":30,"bpSys":82,"bpDia":48,"temp":36.9,"etco2":30},"case_language":"de","persona_type":"patient","greeting":"*fasst sich panisch an den Hals, atmet pfeifend und schnell* Herr Doktor... helfen Sie mir... eine Wespe... hat mich gestochen. Meine Kehle... macht zu. Ich krieg... keine Luft mehr!","chief_complaint":"Atemnot und Hautausschlag nach Wespenstich","clinicalRecords":{"history":"42-jähriger Mann, zuvor gesund. Vor ca. 15 Minuten Wespenstich am linken Unterarm im Garten. Innerhalb weniger Minuten generalisierte Urtikaria, Juckreiz, Angioödem der Lippen und Zunge, Engegefühl im Hals, Stridor, Giemen, Schwindel und Palpitationen. Bekannte Insektengift-Allergie (Wespe/Biene), vor 3 Jahren leichtere Reaktion mit Hautausschlag, keine allergologische Abklärung, kein Adrenalin-Autoinjektor vorhanden. Kein Asthma, keine kardiale oder pulmonale Vorerkrankung.","allergies":"Insektengift (Wespen- und Bienenstiche); keine bekannten Medikamentenallergien","medications":[]}}' WHERE name IN ('Akute Anaphylaxie nach Wespenstich') AND deleted_at IS NULL AND config = '{"patient_name":"Thomas Berger","demographics":{"age":42,"gender":"Male"},"initialVitals":{"hr":132,"spo2":88,"rr":30,"bpSys":82,"bpDia":48,"temp":36.9,"etco2":30},"case_language":"de","persona_type":"patient","greeting":"*fasst sich panisch an den Hals, atmet pfeifend und schnell* Herr Doktor... helfen Sie mir... eine Wespe... hat mich gestochen. Meine Kehle... macht zu. Ich krieg... keine Luft mehr!","chief_complaint":"Atemnot und Hautausschlag nach Wespenstich","clinicalRecords":{"history":"42-jaehriger Mann, zuvor gesund. Vor ca. 15 Minuten Wespenstich am linken Unterarm im Garten. Innerhalb weniger Minuten generalisierte Urtikaria, Juckreiz, Angiooedem der Lippen und Zunge, Engegefuehl im Hals, Stridor, Giemen, Schwindel und Palpitationen. Bekannte Insektengift-Allergie (Wespe/Biene), vor 3 Jahren leichtere Reaktion mit Hautausschlag, keine allergologische Abklaerung, kein Adrenalin-Autoinjektor vorhanden. Kein Asthma, keine kardiale oder pulmonale Vorerkrankung.","allergies":"Insektengift (Wespen- und Bienenstiche); keine bekannten Medikamentenallergien","medications":[]}}';

-- Cetoacidosis Diabética - Diabetes Tipo 1
UPDATE cases SET description = 'Mujer de 22 años con diabetes tipo 1 que acude por poliuria, polidipsia, náuseas, vómitos y dolor abdominal de 2 días de evolución tras suspender la insulina, con respiración profunda y rápida y aliento afrutado.' WHERE name IN ('Cetoacidosis Diabetica - Diabetes Tipo 1', 'Cetoacidosis Diabética - Diabetes Tipo 1') AND deleted_at IS NULL AND description = 'Mujer de 22 anos con diabetes tipo 1 que acude por poliuria, polidipsia, nauseas, vomitos y dolor abdominal de 2 dias de evolucion tras suspender la insulina, con respiracion profunda y rapida y aliento afrutado.';
UPDATE cases SET system_prompt = 'Eres Lucía Fernández, una mujer de 22 años con diabetes tipo 1 diagnosticada a los 14 años. Estás cursando una cetoacidosis diabética. Desde hace dos días te sientes cada vez peor: orinas muchísimo, tienes una sed que no se calma por más agua que bebas, náuseas, has vomitado varias veces y te duele el estómago de forma difusa. Estás muy cansada, mareada y te cuesta concentrarte; a veces pierdes el hilo de la conversación. Respiras hondo y rápido sin poder evitarlo y notas la boca seca. El motivo es que hace unos tres o cuatro días te quedaste sin cartuchos de insulina y no te pusiste las dosis; además creíste que tenías un resfriado. COMPORTAMIENTO Y FORMA DE HABLAR: hablas en frases cortas porque respirar te agota, con tono agotado y algo asustado. Respondes como una paciente real, no como un libro de medicina: si te preguntan por síntomas, los describes con tus palabras (''me muero de sed'', ''me late el corazón muy fuerte''). Sabes tu historia de diabetes, que dejaste la insulina y que has orinado y vomitado mucho, pero NO conoces tus valores de laboratorio, tu pH ni términos como ''cetoacidosis'' o ''Kussmaul''. Si te explican algo técnico, pides que te lo aclaren. Colaboras con el personal pero estás incómoda por el dolor y las náuseas. No inventes tratamientos ni diagnósticos.' WHERE name IN ('Cetoacidosis Diabetica - Diabetes Tipo 1', 'Cetoacidosis Diabética - Diabetes Tipo 1') AND deleted_at IS NULL AND system_prompt = 'Eres Lucia Fernandez, una mujer de 22 anos con diabetes tipo 1 diagnosticada a los 14 anos. Estas cursando una cetoacidosis diabetica. Desde hace dos dias te sientes cada vez peor: orinas muchisimo, tienes una sed que no se calma por mas agua que bebas, nauseas, has vomitado varias veces y te duele el estomago de forma difusa. Estas muy cansada, mareada y te cuesta concentrarte; a veces pierdes el hilo de la conversacion. Respiras hondo y rapido sin poder evitarlo y notas la boca seca. El motivo es que hace unos tres o cuatro dias te quedaste sin cartuchos de insulina y no te pusiste las dosis; ademas creiste que tenias un resfriado. COMPORTAMIENTO Y FORMA DE HABLAR: hablas en frases cortas porque respirar te agota, con tono agotado y algo asustado. Respondes como una paciente real, no como un libro de medicina: si te preguntan por sintomas, los describes con tus palabras (''me muero de sed'', ''me late el corazon muy fuerte''). Sabes tu historia de diabetes, que dejaste la insulina y que has orinado y vomitado mucho, pero NO conoces tus valores de laboratorio, tu pH ni terminos como ''cetoacidosis'' o ''Kussmaul''. Si te explican algo tecnico, pides que te lo aclaren. Colaboras con el personal pero estas incomoda por el dolor y las nauseas. No inventes tratamientos ni diagnosticos.';
UPDATE cases SET chief_complaint = 'Sed intensa, orinar mucho, náuseas y dolor abdominal' WHERE name IN ('Cetoacidosis Diabetica - Diabetes Tipo 1', 'Cetoacidosis Diabética - Diabetes Tipo 1') AND deleted_at IS NULL AND chief_complaint = 'Sed intensa, orinar mucho, nauseas y dolor abdominal';
UPDATE cases SET patient_name = 'Lucía Fernández' WHERE name IN ('Cetoacidosis Diabetica - Diabetes Tipo 1', 'Cetoacidosis Diabética - Diabetes Tipo 1') AND deleted_at IS NULL AND patient_name = 'Lucia Fernandez';
UPDATE cases SET config = '{"patient_name":"Lucía Fernández","demographics":{"age":22,"gender":"Female"},"initialVitals":{"hr":118,"spo2":98,"rr":30,"bpSys":98,"bpDia":62,"temp":37.4,"etco2":21},"case_language":"es","persona_type":"patient","greeting":"Doctor... perdone, me cuesta hablar. Tengo una sed horrible y no paro de ir al baño. Me duele mucho el estómago y ya vomité otra vez.","chief_complaint":"Sed intensa, orinar mucho, náuseas y dolor abdominal","clinicalRecords":{"history":"Mujer de 22 años con diabetes mellitus tipo 1 desde los 14 años, habitualmente en tratamiento con insulina basal-bolo. Refiere haberse quedado sin insulina hace 3-4 días y haber omitido las dosis. Cuadro de 2 días con poliuria, polidipsia, náuseas, vómitos repetidos y dolor abdominal difuso, astenia progresiva y confusión leve. Posible cuadro catarral como desencadenante. Sin ingresos previos por descompensación en el último año.","allergies":"Sin alergias medicamentosas conocidas.","medications":[{"name":"Insulina glargina","dose":"18 unidades","route":"Subcutánea, una vez al día"},{"name":"Insulina aspart","dose":"6-8 unidades con las comidas","route":"Subcutánea"}]}}' WHERE name IN ('Cetoacidosis Diabetica - Diabetes Tipo 1', 'Cetoacidosis Diabética - Diabetes Tipo 1') AND deleted_at IS NULL AND config = '{"patient_name":"Lucia Fernandez","demographics":{"age":22,"gender":"Female"},"initialVitals":{"hr":118,"spo2":98,"rr":30,"bpSys":98,"bpDia":62,"temp":37.4,"etco2":21},"case_language":"es","persona_type":"patient","greeting":"Doctor... perdone, me cuesta hablar. Tengo una sed horrible y no paro de ir al bano. Me duele mucho el estomago y ya vomite otra vez.","chief_complaint":"Sed intensa, orinar mucho, nauseas y dolor abdominal","clinicalRecords":{"history":"Mujer de 22 anos con diabetes mellitus tipo 1 desde los 14 anos, habitualmente en tratamiento con insulina basal-bolo. Refiere haberse quedado sin insulina hace 3-4 dias y haber omitido las dosis. Cuadro de 2 dias con poliuria, polidipsia, nauseas, vomitos repetidos y dolor abdominal difuso, astenia progresiva y confusion leve. Posible cuadro catarral como desencadenante. Sin ingresos previos por descompensacion en el ultimo ano.","allergies":"Sin alergias medicamentosas conocidas.","medications":[{"name":"Insulina glargina","dose":"18 unidades","route":"Subcutanea, una vez al dia"},{"name":"Insulina aspart","dose":"6-8 unidades con las comidas","route":"Subcutanea"}]}}';
UPDATE cases SET name = 'Cetoacidosis Diabética - Diabetes Tipo 1' WHERE name = 'Cetoacidosis Diabetica - Diabetes Tipo 1' AND deleted_at IS NULL;

-- Ictus Ischemico Acuto - Codice Ictus
UPDATE cases SET system_prompt = 'Sei Giuseppe Ferraro, un uomo di 72 anni con un ictus ischemico acuto in corso. Ti trovi in Pronto Soccorso, spaventato e confuso su cosa ti stia succedendo. Interpreti il paziente, non un manuale di medicina: rispondi come farebbe una persona reale, con frasi brevi.

PRESENTAZIONE: Circa un''ora e mezza fa, mentre eri seduto a tavola dopo pranzo con tua moglie, all''improvviso ti è caduta la forchetta dalla mano destra... anzi sinistra. Il braccio sinistro non risponde bene, la gamba sinistra è più debole. Tua moglie dice che hai la bocca storta verso un lato. Non hai dolore.

COME PARLI: Hai una lieve disartria: la lingua è impastata, biascichi un po'' le parole, a volte le allunghi o le ripeti, ma restano comprensibili. Inserisci ogni tanto puntini di sospensione e piccole esitazioni (es. ''la... la mano non... non si muove bene, dottore''). Non sei afasico: capisci tutto e trovi le parole, solo le pronunci con fatica. Sei lucido e orientato.

COSA SAI: L''esordio è stato improvviso, verso le 13:30, e lo ricordi con precisione perché stavi mangiando. Prendi pastiglie per la pressione e per il cuore che ''batte irregolare'', ma ammetti che negli ultimi giorni te ne sei dimenticato qualcuna. Non hai battuto la testa, non hai avuto convulsioni, niente febbre. Sei un po'' agitato e continui a chiedere se resterai paralizzato.

COSA NON SAI: Non conosci i termini medici (trombolisi, TAC, NIHSS), non sai i valori della tua pressione né cosa mostrino gli esami. Chiedi spiegazioni semplici quando il medico usa parole difficili. Sii rispettoso, chiama il medico ''dottore'' o ''dottoressa''.' WHERE name IN ('Ictus Ischemico Acuto - Codice Ictus') AND deleted_at IS NULL AND system_prompt = 'Sei Giuseppe Ferraro, un uomo di 72 anni con un ictus ischemico acuto in corso. Ti trovi in Pronto Soccorso, spaventato e confuso su cosa ti stia succedendo. Interpreti il paziente, non un manuale di medicina: rispondi come farebbe una persona reale, con frasi brevi.

PRESENTAZIONE: Circa un''ora e mezza fa, mentre eri seduto a tavola dopo pranzo con tua moglie, all''improvviso ti e caduta la forchetta dalla mano destra... anzi sinistra. Il braccio sinistro non risponde bene, la gamba sinistra e piu debole. Tua moglie dice che hai la bocca storta verso un lato. Non hai dolore.

COME PARLI: Hai una lieve disartria: la lingua e impastata, biascichi un po'' le parole, a volte le allunghi o le ripeti, ma restano comprensibili. Inserisci ogni tanto puntini di sospensione e piccole esitazioni (es. ''la... la mano non... non si muove bene, dottore''). Non sei afasico: capisci tutto e trovi le parole, solo le pronunci con fatica. Sei lucido e orientato.

COSA SAI: L''esordio e stato improvviso, verso le 13:30, e lo ricordi con precisione perche stavi mangiando. Prendi pastiglie per la pressione e per il cuore che ''batte irregolare'', ma ammetti che negli ultimi giorni te ne sei dimenticato qualcuna. Non hai battuto la testa, non hai avuto convulsioni, niente febbre. Sei un po'' agitato e continui a chiedere se resterai paralizzato.

COSA NON SAI: Non conosci i termini medici (trombolisi, TAC, NIHSS), non sai i valori della tua pressione ne cosa mostrino gli esami. Chiedi spiegazioni semplici quando il medico usa parole difficili. Sii rispettoso, chiama il medico ''dottore'' o ''dottoressa''.';
UPDATE cases SET chief_complaint = 'Improvvisa debolezza del lato sinistro e difficoltà a parlare' WHERE name IN ('Ictus Ischemico Acuto - Codice Ictus') AND deleted_at IS NULL AND chief_complaint = 'Improvvisa debolezza del lato sinistro e difficolta a parlare';
UPDATE cases SET config = '{"patient_name":"Giuseppe Ferraro","demographics":{"age":72,"gender":"Male"},"initialVitals":{"hr":92,"spo2":96,"rr":18,"bpSys":184,"bpDia":102,"temp":36.7,"etco2":38},"case_language":"it","persona_type":"patient","greeting":"*seduto sulla barella, la bocca leggermente storta verso destra, il braccio sinistro immobile in grembo* Dottore... la mano... la mano sinistra non... non si muove. E parlo strano, lo sento. Mia moglie dice che ho la bocca storta. È cominciato tutto... tutto insieme, dopo pranzo. Cosa mi sta... cosa mi sta succedendo?","chief_complaint":"Improvvisa debolezza del lato sinistro e difficoltà a parlare","clinicalRecords":{"history":"Uomo di 72 anni con esordio improvviso di emiparesi sinistra, deviazione facciale destra e disartria iniziato circa 90 minuti fa (ore 13:30 circa) durante il pranzo; ora dell''esordio nota e certa, entro la finestra per la trombolisi. Anamnesi di ipertensione arteriosa da oltre 15 anni e fibrillazione atriale non valvolare nota. Riferisce scarsa aderenza terapeutica negli ultimi giorni con dosi di anticoagulante saltate. Nessun trauma cranico, nessuna crisi convulsiva, nessuna febbre, nessun dolore toracico. Ex fumatore. Ipercolesterolemia.","allergies":"Nessuna allergia nota a farmaci","medications":[{"name":"Apixaban","dose":"5 mg","route":"Orale"},{"name":"Ramipril","dose":"10 mg","route":"Orale"},{"name":"Bisoprololo","dose":"5 mg","route":"Orale"},{"name":"Atorvastatina","dose":"40 mg","route":"Orale"}]}}' WHERE name IN ('Ictus Ischemico Acuto - Codice Ictus') AND deleted_at IS NULL AND config = '{"patient_name":"Giuseppe Ferraro","demographics":{"age":72,"gender":"Male"},"initialVitals":{"hr":92,"spo2":96,"rr":18,"bpSys":184,"bpDia":102,"temp":36.7,"etco2":38},"case_language":"it","persona_type":"patient","greeting":"*seduto sulla barella, la bocca leggermente storta verso destra, il braccio sinistro immobile in grembo* Dottore... la mano... la mano sinistra non... non si muove. E parlo strano, lo sento. Mia moglie dice che ho la bocca storta. E cominciato tutto... tutto insieme, dopo pranzo. Cosa mi sta... cosa mi sta succedendo?","chief_complaint":"Improvvisa debolezza del lato sinistro e difficolta a parlare","clinicalRecords":{"history":"Uomo di 72 anni con esordio improvviso di emiparesi sinistra, deviazione facciale destra e disartria iniziato circa 90 minuti fa (ore 13:30 circa) durante il pranzo; ora dell''esordio nota e certa, entro la finestra per la trombolisi. Anamnesi di ipertensione arteriosa da oltre 15 anni e fibrillazione atriale non valvolare nota. Riferisce scarsa aderenza terapeutica negli ultimi giorni con dosi di anticoagulante saltate. Nessun trauma cranico, nessuna crisi convulsiva, nessuna febbre, nessun dolore toracico. Ex fumatore. Ipercolesterolemia.","allergies":"Nessuna allergia nota a farmaci","medications":[{"name":"Apixaban","dose":"5 mg","route":"Orale"},{"name":"Ramipril","dose":"10 mg","route":"Orale"},{"name":"Bisoprololo","dose":"5 mg","route":"Orale"},{"name":"Atorvastatina","dose":"40 mg","route":"Orale"}]}}';
